package br.com.admeclesial.domain.pessoa; import jakarta.persistence.*; import java.time.LocalDate; import java.util.UUID; @Entity @Table(name="membro_familia",schema="adm_eclesial") public class MembroFamilia { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,updatable=false) UUID uuid; @Column(name="familia_id",nullable=false) Long familiaId; @Column(name="pessoa_id",nullable=false) Long pessoaId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) TipoMembroFamilia tipo; @Column(name="data_inicio",nullable=false) LocalDate dataInicio; @Column(name="data_fim") LocalDate dataFim; @PrePersist void pre(){if(uuid==null)uuid=UUID.randomUUID();} public Long getId(){return id;}public UUID getUuid(){return uuid;}public Long getFamiliaId(){return familiaId;}public Long getPessoaId(){return pessoaId;}public TipoMembroFamilia getTipo(){return tipo;}public LocalDate getDataInicio(){return dataInicio;}public LocalDate getDataFim(){return dataFim;}public void setFamiliaId(Long v){familiaId=v;}public void setPessoaId(Long v){pessoaId=v;}public void setTipo(TipoMembroFamilia v){tipo=v;}public void setDataInicio(LocalDate v){dataInicio=v;}public void setDataFim(LocalDate v){dataFim=v;} }